#include <bits/stdc++.h>
using namespace std;

int main() {
    const int M = 7;
    vector<int> table(M, -1);
    for (int key : {10, 17, 24}) {
        int pos = key % M;
        while (table[pos] != -1) pos = (pos + 1) % M;
        table[pos] = key;
    }
    for (int x : table) cout << x << " ";
    cout << "\n";
    return 0;
}

